{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/brain-fuel/ironframe/schema/ironframe-v1.schema.json",
  "title": "Ironframe manifest, version 1",
  "description": "ironframe.yaml: the dependencies an application reads from its configuration, and for each environment whether each one is the real dependency or a twin.",
  "type": "object",
  "additionalProperties": false,
  "required": ["version", "project", "dependencies", "environments"],
  "properties": {
    "version": { "const": 1, "description": "The manifest version." },
    "project": { "$ref": "#/$defs/name", "description": "The project's name; it prefixes every container, compose project and cloud resource." },
    "dependencies": {
      "type": "object",
      "description": "The dependencies the application has, each with the settings it reads them through.",
      "propertyNames": { "$ref": "#/$defs/name" },
      "additionalProperties": { "$ref": "#/$defs/dependency" }
    },
    "environments": {
      "type": "object",
      "minProperties": 1,
      "propertyNames": { "$ref": "#/$defs/name" },
      "additionalProperties": { "$ref": "#/$defs/environment" }
    }
  },
  "$defs": {
    "name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_-]{0,39}$"
    },
    "port": { "type": "integer", "minimum": 1, "maximum": 65535 },
    "credentials": {
      "type": "string",
      "pattern": "^(env|file|aws-secretsmanager|gcp-secretmanager|azure-keyvault|vault):.+$",
      "description": "A reference to credentials, <scheme>:<location>. Ironframe passes it on and never reads the secret."
    },
    "stringMap": {
      "type": "object",
      "additionalProperties": { "type": "string" }
    },
    "dependency": {
      "type": "object",
      "additionalProperties": false,
      "required": ["settings"],
      "properties": {
        "description": { "type": "string" },
        "settings": {
          "type": "object",
          "minProperties": 1,
          "propertyNames": { "pattern": "^[A-Za-z_][A-Za-z0-9_]*$" },
          "additionalProperties": { "type": "string" },
          "description": "Setting name to template; the template may use ${endpoint}, ${host}, ${port}, ${credentials}, ${kind} and ${name}."
        }
      }
    },
    "environment": {
      "type": "object",
      "additionalProperties": false,
      "required": ["runtime", "dependencies"],
      "properties": {
        "runtime": { "enum": ["podman", "aws", "gcp", "azure"] },
        "cloud": {
          "type": "object",
          "description": "Inputs for a cloud runtime, passed to the provider and every module that takes them. aws needs region, vpc_id and subnet_ids; gcp needs project and region; azure needs location and resource_group_name.",
          "properties": {
            "modules": { "type": "string", "description": "A module source to use instead of the released modules." }
          }
        },
        "dependencies": {
          "type": "object",
          "propertyNames": { "$ref": "#/$defs/name" },
          "additionalProperties": { "$ref": "#/$defs/binding" }
        },
        "sync": {
          "type": "array",
          "items": { "$ref": "#/$defs/syncTarget" }
        },
        "config_service": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "image": { "type": "string", "minLength": 1 },
            "port": { "$ref": "#/$defs/port" }
          }
        }
      }
    },
    "binding": {
      "type": "object",
      "minProperties": 1,
      "maxProperties": 1,
      "additionalProperties": false,
      "properties": {
        "real": { "$ref": "#/$defs/real" },
        "twin": { "$ref": "#/$defs/twin" }
      }
    },
    "real": {
      "type": "object",
      "additionalProperties": false,
      "required": ["endpoint"],
      "properties": {
        "endpoint": { "type": "string", "minLength": 1 },
        "credentials": { "$ref": "#/$defs/credentials" },
        "image": { "type": "string", "minLength": 1 },
        "ports": { "type": "array", "items": { "$ref": "#/$defs/port" } },
        "env": { "$ref": "#/$defs/stringMap" }
      }
    },
    "twin": {
      "type": "object",
      "additionalProperties": false,
      "required": ["image", "version", "conformance", "ports"],
      "properties": {
        "image": { "type": "string", "minLength": 1, "description": "The image name without a tag." },
        "version": { "type": "string", "minLength": 1, "description": "The image tag, which is the twin's version." },
        "config": { "type": "object", "description": "Handed to the twin as JSON in TWIN_CONFIG." },
        "conformance": {
          "description": "The conformance level the twin's release declares, or where to read it: a report beside the manifest, or an image label. A declared level must match the report's.",
          "oneOf": [
            { "type": "string", "minLength": 1 },
            {
              "type": "object",
              "additionalProperties": false,
              "minProperties": 1,
              "properties": {
                "level": { "type": "string", "minLength": 1, "description": "The level declared: the report's level name, its number, or <number>-<name>." },
                "report": { "type": "string", "minLength": 1, "description": "The twin release's conformance report, a JSON file relative to the manifest." },
                "image_label": { "type": "string", "minLength": 1, "description": "The image label holding the level, read by up." }
              }
            }
          ]
        },
        "ports": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/port" } },
        "env": { "$ref": "#/$defs/stringMap" },
        "endpoint": { "type": "string", "minLength": 1 },
        "credentials": { "$ref": "#/$defs/credentials" },
        "seed": { "type": "integer", "minimum": 0, "description": "The seed of the twin's random choices, handed over as seed in TWIN_CONFIG." },
        "contract": { "type": "string", "minLength": 1, "description": "The contract a twin serving several should serve, handed over as contract in TWIN_CONFIG." },
        "state": {
          "description": "A state to force once the twin answers: a JSON file relative to the manifest, or the state itself.",
          "oneOf": [{ "type": "object" }, { "type": "string", "minLength": 1 }]
        },
        "faults": {
          "type": "array",
          "description": "Faults to raise once the twin answers, in order.",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["name"],
            "properties": {
              "name": { "type": "string", "minLength": 1 },
              "params": { "type": "object", "additionalProperties": { "oneOf": [{ "type": "string" }, { "type": "integer" }] } }
            }
          }
        },
        "admin": {
          "type": "object",
          "additionalProperties": false,
          "description": "Where the twin's control plane is reached: a port published on podman, or a URL.",
          "properties": {
            "port": { "$ref": "#/$defs/port" },
            "container_port": { "$ref": "#/$defs/port" },
            "url": { "type": "string", "minLength": 1 }
          }
        },
        "protocol": { "enum": ["http", "tcp"], "description": "What the twin serves on its first port; on gcp, tcp runs it on Compute Engine rather than Cloud Run. Default http." },
        "advertise_variable": { "type": "string", "minLength": 1, "description": "An environment variable the twin reads the address to advertise from, set to the endpoint's host:port." }
      }
    },
    "syncTarget": {
      "type": "object",
      "minProperties": 1,
      "maxProperties": 1,
      "additionalProperties": false,
      "properties": {
        "env_file": {
          "type": "object",
          "additionalProperties": false,
          "required": ["path"],
          "properties": { "path": { "type": "string", "minLength": 1 } }
        },
        "aws_appconfig": {
          "type": "object",
          "additionalProperties": false,
          "required": ["region", "application", "profile"],
          "properties": {
            "region": { "type": "string", "minLength": 1 },
            "application": { "type": "string", "minLength": 1 },
            "environment": { "type": "string", "minLength": 1 },
            "profile": { "type": "string", "minLength": 1 },
            "deployment_strategy": { "type": "string", "minLength": 1 }
          }
        },
        "gcp_parameter_manager": {
          "type": "object",
          "additionalProperties": false,
          "required": ["project", "parameter"],
          "properties": {
            "project": { "type": "string", "minLength": 1 },
            "location": { "type": "string", "minLength": 1 },
            "parameter": { "type": "string", "pattern": "^[A-Za-z0-9_-]{1,63}$" }
          }
        },
        "azure_app_configuration": {
          "type": "object",
          "additionalProperties": false,
          "required": ["endpoint"],
          "properties": {
            "endpoint": { "type": "string", "pattern": "^https://" },
            "label": { "type": "string", "minLength": 1 },
            "prefix": { "type": "string" },
            "connection_string_env": { "type": "string", "minLength": 1 }
          }
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/brain-fuel/ironframe/schema/attestation-v1.schema.json",
  "title": "Environment attestation, version 1",
  "description": "Which endpoint each dependency of one run reached, and whether it was the real dependency or a stand-in. Readers ignore fields they do not know.",
  "type": "object",
  "required": [
    "format",
    "version",
    "environment",
    "run",
    "dependencies"
  ],
  "properties": {
    "format": {
      "const": "environment-attestation"
    },
    "version": {
      "const": 1
    },
    "environment": {
      "type": "string",
      "minLength": 1
    },
    "run": {
      "type": "object",
      "required": [
        "id",
        "started_at",
        "recorded_at"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1
        },
        "started_at": {
          "type": "string",
          "format": "date-time"
        },
        "recorded_at": {
          "type": "string",
          "format": "date-time"
        }
      }
    },
    "producer": {
      "type": "object",
      "required": [
        "name",
        "version"
      ],
      "properties": {
        "name": {
          "type": "string"
        },
        "version": {
          "type": "string"
        }
      }
    },
    "dependencies": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/dependency"
      }
    },
    "architecture": {
      "description": "The CALM architecture the wiring was resolved from, by identity: the documents' digests, the resolved topology's digest (the planned wiring) and the elements the run involved.",
      "type": "object",
      "required": [
        "document",
        "digest"
      ],
      "properties": {
        "document": {
          "type": "string"
        },
        "digest": {
          "type": "string",
          "pattern": "^sha256:[0-9a-f]{64}$"
        },
        "unique_id": {
          "type": "string"
        },
        "decorators": {
          "type": "string"
        },
        "decorators_digest": {
          "type": "string",
          "pattern": "^sha256:[0-9a-f]{64}$"
        },
        "topology_digest": {
          "type": "string",
          "pattern": "^sha256:[0-9a-f]{64}$"
        },
        "elements": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "application": {
      "description": "The application the run exercised: its architecture node, the contract it implements and what implemented it.",
      "type": "object",
      "required": [
        "node",
        "contract",
        "implementation"
      ],
      "properties": {
        "node": {
          "type": "string"
        },
        "contract": {
          "$ref": "#/$defs/contract"
        },
        "implementation": {
          "$ref": "#/$defs/implementation"
        }
      }
    },
    "execution": {
      "description": "What the document records: wiring alone (wired), a run under way (running) or a completed run (completed), with its outcome. exit_code and finished_at are present exactly when completed.",
      "type": "object",
      "required": [
        "status"
      ],
      "properties": {
        "status": {
          "enum": [
            "wired",
            "running",
            "completed"
          ]
        },
        "command": {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        "exit_code": {
          "type": "integer"
        },
        "finished_at": {
          "type": "string",
          "format": "date-time"
        },
        "environment_run": {
          "type": "string"
        }
      }
    }
  },
  "$defs": {
    "dependency": {
      "type": "object",
      "required": [
        "name",
        "endpoint",
        "reached",
        "kind"
      ],
      "properties": {
        "name": {
          "type": "string",
          "minLength": 1
        },
        "endpoint": {
          "type": "string",
          "minLength": 1
        },
        "reached": {
          "type": "boolean"
        },
        "kind": {
          "enum": [
            "real",
            "stand-in"
          ]
        },
        "stand_in": {
          "type": "object",
          "required": [
            "product",
            "version",
            "conformance"
          ],
          "properties": {
            "product": {
              "type": "string",
              "minLength": 1
            },
            "version": {
              "type": "string",
              "minLength": 1
            },
            "conformance": {
              "type": "string",
              "minLength": 1
            },
            "seed": {
              "type": "integer",
              "minimum": 0
            },
            "history_digest": {
              "type": "string",
              "pattern": "^sha256:[0-9a-f]{64}$"
            },
            "history_entries": {
              "type": "integer",
              "minimum": 0
            },
            "stands_in_for": {
              "$ref": "#/$defs/contract",
              "description": "The contract identity the stand-in stands in for."
            }
          }
        },
        "node": {
          "type": "string",
          "description": "The architecture node the dependency is."
        },
        "edge": {
          "type": "string",
          "description": "The relationship the application reached it through."
        },
        "contract": {
          "$ref": "#/$defs/contract",
          "description": "The contract the dependency's binding had to satisfy."
        },
        "implementation": {
          "$ref": "#/$defs/implementation",
          "description": "The real provider or the fixture that implemented the dependency."
        },
        "completed": {
          "type": "object",
          "required": [
            "reached"
          ],
          "description": "What was observed when the run completed; only on a completed run.",
          "properties": {
            "reached": {
              "type": "boolean"
            },
            "history_digest": {
              "type": "string",
              "pattern": "^sha256:[0-9a-f]{64}$"
            },
            "history_entries": {
              "type": "integer",
              "minimum": 0
            }
          }
        }
      },
      "if": {
        "properties": {
          "kind": {
            "const": "stand-in"
          }
        }
      },
      "then": {
        "required": [
          "stand_in"
        ]
      },
      "else": {
        "not": {
          "required": [
            "stand_in"
          ]
        }
      }
    },
    "contract": {
      "type": "object",
      "required": [
        "package",
        "version"
      ],
      "properties": {
        "package": {
          "type": "string",
          "minLength": 1
        },
        "version": {
          "type": "string",
          "minLength": 1
        },
        "abilities": {
          "type": "array",
          "items": {
            "type": "string"
          }
        }
      }
    },
    "implementation": {
      "type": "object",
      "required": [
        "kind",
        "product",
        "version"
      ],
      "properties": {
        "kind": {
          "enum": [
            "real-provider",
            "fixture",
            "application"
          ]
        },
        "product": {
          "type": "string"
        },
        "version": {
          "type": "string"
        },
        "commit": {
          "type": "string"
        },
        "image_digest": {
          "type": "string"
        }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/brain-fuel/ironframe/schema/calm/ironframe-contract.decorator.schema.json",
  "title": "Ironframe contract decorator",
  "description": "The LawSpec contract identity a CALM element must satisfy: what an application node implements, what a dependency node must provide, or which of the application's dependency abilities a connects relationship carries and the settings the application reads it through. Extends CALM 1.2's base decorator.",
  "allOf": [
    {
      "$ref": "#/$defs/calm-decorator"
    }
  ],
  "properties": {
    "type": {
      "const": "ironframe-contract"
    },
    "data": {
      "type": "object",
      "minProperties": 1,
      "maxProperties": 1,
      "additionalProperties": false,
      "properties": {
        "application": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "package",
            "version"
          ],
          "properties": {
            "package": {
              "type": "string",
              "pattern": "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*$",
              "description": "A LawSpec package name, as its lawspec-package.json gives it."
            },
            "version": {
              "type": "string",
              "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\\+[0-9A-Za-z.-]+)?$",
              "description": "An exact semantic version."
            },
            "description": {
              "type": "string"
            }
          },
          "description": "The LawSpec package whose laws the application node is checked against."
        },
        "dependency": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "package",
            "version",
            "abilities"
          ],
          "properties": {
            "package": {
              "type": "string",
              "pattern": "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*$",
              "description": "A LawSpec package name, as its lawspec-package.json gives it."
            },
            "version": {
              "type": "string",
              "minLength": 1,
              "description": "A semantic version requirement, as Cargo writes one: \">=0.1.0, <0.2.0\", \"^0.1\", \"~0.1.0\", \"=0.1.0\" or \"*\"."
            },
            "abilities": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*::ability::[A-Z][A-Za-z0-9_]*$",
                "description": "A LawSpec ability by its resolved identity, unit::ability::Name."
              }
            },
            "conformance": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "accept"
              ],
              "properties": {
                "accept": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "string",
                    "minLength": 1
                  }
                }
              },
              "description": "The conformance levels a twin bound here must have, by name or number."
            },
            "description": {
              "type": "string"
            }
          },
          "description": "The contract a dependency node's binding must satisfy, in every environment."
        },
        "connection": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "consumes",
            "settings"
          ],
          "properties": {
            "consumes": {
              "type": "array",
              "minItems": 1,
              "items": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*::ability::[A-Z][A-Za-z0-9_]*$",
                "description": "A LawSpec ability by its resolved identity, unit::ability::Name."
              },
              "description": "The source application's abilities whose production handler reaches the destination."
            },
            "settings": {
              "type": "object",
              "minProperties": 1,
              "additionalProperties": {
                "type": "string"
              },
              "description": "Setting name to template over the bound endpoint: ${endpoint}, ${host}, ${port}, ${credentials}, ${kind}, ${name}."
            }
          }
        }
      },
      "oneOf": [
        {
          "required": [
            "application"
          ]
        },
        {
          "required": [
            "dependency"
          ]
        },
        {
          "required": [
            "connection"
          ]
        }
      ]
    }
  },
  "$defs": {
    "calm-decorator": {
      "type": "object",
      "properties": {
        "$schema": {
          "type": "string"
        },
        "unique-id": {
          "type": "string",
          "minLength": 1
        },
        "type": {
          "type": "string"
        },
        "target": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "applies-to": {
          "type": "array",
          "items": {
            "type": "string"
          },
          "minItems": 1
        },
        "data": {
          "type": "object",
          "minProperties": 1
        }
      },
      "required": [
        "unique-id",
        "type",
        "target",
        "applies-to",
        "data"
      ]
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/brain-fuel/ironframe/schema/calm/ironframe-binding.decorator.schema.json",
  "title": "Ironframe binding decorator",
  "description": "What one CALM node is in one environment: the real dependency, a twin standing in for it with the contract identity it stands in for, or, for an application node, how the application is deployed. Extends CALM 1.2's base decorator.",
  "allOf": [
    {
      "$ref": "#/$defs/calm-decorator"
    }
  ],
  "properties": {
    "type": {
      "const": "ironframe-binding"
    },
    "data": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "environment"
      ],
      "properties": {
        "environment": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]*$"
        },
        "real": {
          "type": "object",
          "required": [
            "endpoint"
          ],
          "properties": {
            "endpoint": {
              "type": "string",
              "minLength": 1
            },
            "provider": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "name",
                "version"
              ],
              "properties": {
                "name": {
                  "type": "string",
                  "minLength": 1
                },
                "version": {
                  "type": "string",
                  "minLength": 1
                }
              }
            }
          },
          "description": "The real dependency, with the fields of ironframe.yaml's real binding and the provider it is."
        },
        "twin": {
          "type": "object",
          "required": [
            "image",
            "version",
            "conformance",
            "ports",
            "stands-in-for"
          ],
          "properties": {
            "stands-in-for": {
              "type": "object",
              "additionalProperties": false,
              "required": [
                "package",
                "version",
                "abilities"
              ],
              "properties": {
                "package": {
                  "type": "string",
                  "pattern": "^[a-z][a-z0-9_]*(\\.[a-z][a-z0-9_]*)*$",
                  "description": "A LawSpec package name, as its lawspec-package.json gives it."
                },
                "version": {
                  "type": "string",
                  "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)(-[0-9A-Za-z.-]+)?(\\+[0-9A-Za-z.-]+)?$",
                  "description": "An exact semantic version."
                },
                "abilities": {
                  "type": "array",
                  "minItems": 1,
                  "items": {
                    "type": "string",
