    "unique_id": "calm-shop",
    "decorators": "shop.decorators.json",
    "decorators_digest": "sha256:cc8b0b54398742dc6b42dafa1cc181746721679042cf0535f6833138bac19564"
  },
  "environment": "twin",
  "project": "calm-shop",
  "runtime": "podman",
  "applications": [
    {
      "node": "adoptions-audit",
      "name": "Adoptions audit",
      "contract": {
        "package": "shop.adoptions",
        "version": "0.1.0"
      },
      "deployment": {
        "deployment": "process",
        "command": [
          "go",
          "run",
          "./cmd/shop",
          "audit"
        ],
        "dir": "../app"
      },
      "version": "0.1.0",
      "edges": [
        "audit-reads-adoptions"
      ]
    },
    {
      "node": "adoptions-service",
      "name": "Adoptions service",
      "contract": {
        "package": "shop.adoptions",
        "version": "0.1.0"
      },
      "deployment": {
        "deployment": "external"
      },
      "version": "0.1.0",
      "edges": [
        "service-publishes-adoptions",
        "service-registers-pets"
      ]
    }
  ],
  "dependencies": [
    {
      "node": "adoptions-log",
      "name": "Adoptions log",
      "contract": {
        "package": "lawtwin.kafka",
        "version": ">=0.1.0, <0.2.0",
        "abilities": [
          "lawtwin.kafka::ability::Broker"
        ]
      },
      "binding": "adoptions-log-twin",
      "kind": "twin",
      "twin": {
        "image": "lawtwin/kafka",
        "version": "0.1.0",
        "stands_in_for": {
          "package": "lawtwin.kafka",
          "version": "0.1.0",
          "abilities": [
            "lawtwin.kafka::ability::Broker"
          ]
        },
        "conformance": "answers",
        "seed": 42
      },
      "consumers": 2
    },
    {
      "node": "pet-registry",
      "name": "Pet registry",
      "contract": {
        "package": "lawtwin.petstore",
        "version": "^0.1",
        "abilities": [
          "lawtwin.petstore::ability::PetApi"
        ]
      },
      "binding": "pet-registry-twin",
      "kind": "twin",
      "twin": {
        "image": "lawtwin/http",
        "version": "0.1.0",
        "stands_in_for": {
          "package": "lawtwin.petstore",
          "version": "0.1.0",
          "abilities": [
            "lawtwin.petstore::ability::PetApi"
          ]
        },
        "conformance": "conformant",
        "seed": 42
      },
      "consumers": 1
    }
  ],
  "edges": [
    {
      "relationship": "service-publishes-adoptions",
      "source": "adoptions-service",
      "destination": "adoptions-log",
      "protocol": "TCP",
      "consumes": [
        "shop.adoptions::ability::Adoptions"
      ],
      "settings": {
        "KAFKA_BOOTSTRAP_SERVERS": "${endpoint}"
      },
      "kind": "twin"
    },
    {
      "relationship": "service-registers-pets",
      "source": "adoptions-service",
      "destination": "pet-registry",
      "protocol": "HTTP",
      "consumes": [
        "shop.adoptions::ability::Pets"
      ],
      "settings": {
        "PETSTORE_URL": "${endpoint}"
      },
      "kind": "twin"
    },
    {
      "relationship": "audit-reads-adoptions",
      "source": "adoptions-audit",
      "destination": "adoptions-log",
      "protocol": "TCP",
      "consumes": [
        "shop.adoptions::ability::Adoptions"
      ],
      "settings": {
        "KAFKA_BOOTSTRAP_SERVERS": "${endpoint}"
      },
      "kind": "twin"
    }
  ]
}

